// TH18 v1.00a st05bs.ecl.txt:160-292, Boss2 (stage 5 extra-boss non-spell 2).
// Source t0 = target frame 124 after the 120-frame practice-shell buffer.
// Source t0 data: 5 parents (type19/color4, mode5 ring) each run EX records 0-14:
//   ANIM a1 -> INVULN200 -> WAIT(rank) -> SHOOT4 (type16/color8) -> WAIT4
//   -> SHOOT4 (type37/color8) -> GOTO back to INVULN. Children start at record12:
//   PLAYSOUND38 -> WAIT60 -> VELTIME120 r=1.0/1.5/1.5/1.6, s=4000000, m=2*pi.
const TIME_LIMIT: int = 2522;
const SOURCE_LIMIT: int = 2400;
const OPENING_BUFFER: int = 120;
const TH18_BIG_BALL2: int = 656; // type19, radius 8.5, colors 0-7
const TH18_STAR_R: int = 608;    // type16, radius 4
const TH18_STAR_L: int = 944;    // type37, radius 4

// VELTIME: direction read on entry is current angle + 2*pi*U (uniform full circle).
// It adds delta=(target-0.8)/120 to the velocity vector for 120 ticks; the initial
// 0.8 velocity vector is kept. dir is sampled per child at emit time (same uniform
// distribution; only World-RNG stream order differs from the source entry sampling).
xformdef VELTIME(d: fx, dir: angle) {
    wait(60);
    @120 set_gravity(d*cos(dir), d*sin(dir));
    set_gravity(0fx, 0fx);
}

// Mode-1 fan, N=4, step 45deg: +22.5, -22.5, +67.5, -67.5 relative to parent angle.
sub split(shape: int, d: fx) {
    var base: angle = $self_angle;
    var x: fx = $self_x;
    var y: fx = $self_y;
    var ca: angle = base + (4096 as angle);
    _ = fire(shape, 8, x, y, 0.8fx, ca, VELTIME(d, ca+(rand(65536) as angle)), none);
    ca = base - (4096 as angle);
    _ = fire(shape, 8, x, y, 0.8fx, ca, VELTIME(d, ca+(rand(65536) as angle)), none);
    ca = base + (12288 as angle);
    _ = fire(shape, 8, x, y, 0.8fx, ca, VELTIME(d, ca+(rand(65536) as angle)), none);
    ca = base - (12288 as angle);
    _ = fire(shape, 8, x, y, 0.8fx, ca, VELTIME(d, ca+(rand(65536) as angle)), none);
}

// Source EX loop of each parent bullet. Parent task first runs one frame after spawn;
// the first WAIT is shortened by one frame to put the first split at source spawn+wait.
async sub PARENT() {
    var rank: int = global(GVAR_RANK);
    var w: int = 4;
    var target: fx = 1.5fx;
    if rank == 0 { w = 9; target = 1fx; }
    if rank == 1 { w = 4; target = 1.5fx; }
    if rank == 2 { w = 3; target = 1.5fx; }
    if rank == 3 { w = 3; target = 1.6fx; }
    var d: fx = (target-0.8fx)/120fx;
    wait(w-1);
    loop {
        split(TH18_STAR_R, d);
        wait(4);
        split(TH18_STAR_L, d);
        wait(w);
    }
}

// Boss2_at: mode5 fixed ring, alpha=pi/2, delta=pi/9, N=5, M=1, speed 4.
// sh_ring adds the half-road offset by baking pi/5 into the base (126deg).
sub volley() {
    sh_reset(0);
    sh_sprite(0, TH18_BIG_BALL2, 4);
    sh_count(0, 5, 1);
    sh_ring(0, 1);
    sh_aim(0, 0);
    sh_angle(0, 126deg, 0deg);
    sh_speed(0, 4fx, 0fx);
    sh_dist(0, -16fx); // ANIM a1: position -= 4*initial velocity
    sh_task(0, PARENT);
    sh_fire(0);
}

async sub boss_attack() {
    set_invuln(65535);
    set_hitbox(24fx);  // source setHitbox(48,48); ordinary circle width*0.5
    set_hurtbox(20fx); // source setHurtbox(40,40); width*0.5
    set_self_int(0, 50); // movement helper at rest before the first moveRand
    set_self_fx(0, 0fx);
    set_self_fx(1, 0fx);
    wait(OPENING_BUFFER);
    var until: int = $frame+SOURCE_LIMIT;
    // Source entry cleanup/setup then wait(90)+EffChargePoint3+wait(80).
    wait(170);
    loop {
        if $frame >= until { break; }
        volley();
        wait(200);
        card_move_rand();
        card_wait(60);
    }
    loop { wait(1); }
}

async sub phase_timer() {
    loop { wait(1); }
}
async sub control_main() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1); // control enemy never body-collides
    phase_begin(0, phase_timer, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}
sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control_main);
    _ = spawn_enemy(0fx, 128fx, 100000, 0, 0, 0, boss_attack);
    loop { wait(600); }
}

// TH18 v1.00a st05bs.txt:171/205/235 moveRand(50,0,0.8f) under moveLimit(0,128,280,96).
// int slot0 = next-step count; fx0/1 = logical unit direction. No source read in Boss2
// depends on these shared slots (source $I0/$I1=60/1 are never consumed by Boss2_at).
// Source update order is move -> ECL; target is ECL -> phase5, so the next source step is
// armed in advance, as in the existing stage-5 shell.
sub card_arm_next_step() {
    var k: int = self_int(0)+1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < 50 { speed = ((50-k) as fx) * 0.8fx / 50fx; } // 0.8*(1-k/50), linear
    var nx: fx = $self_x+self_fx(0)*speed;
    var ny: fx = $self_y+self_fx(1)*speed;
    if nx < -140fx { nx = -140fx; }
    if nx > 140fx { nx = 140fx; }
    if ny < 80fx { ny = 80fx; }
    if ny > 176fx { ny = 176fx; }
    move_vel_xy(0, nx-$self_x, ny-$self_y, EASE_LINEAR);
}
sub card_begin_angle(a: angle) {
    set_self_fx(0, cos(a));
    set_self_fx(1, sin(a));
    set_self_int(0, 0);
    card_arm_next_step();
}
// Native direction selection: inner region x+-70, y104..152, outer region actual
// x+-140, y80..176. r = signed unit BAM (pi*U); keep unwrapped values before fabs.
sub card_move_rand() {
    var r: int = rand(65536)-32768;
    var a: int = r/3;
    if $self_x < -70fx {
        a = r/3;
    } else if $self_x > 70fx {
        a = r/3+32768;
        if a > 32768 { a = a-65536; }
    } else {
        a = r/4;
        var choose: int = rand(65536)%3;
        if $player_x > $self_x {
            if choose == 0 { a = a+32768; }
        } else {
            if choose != 0 { a = a+32768; }
        }
    }
    if $self_y < 104fx {
        if a < 0 { a = -a; }
    } else if $self_y > 152fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    // Native +-pi/2 guard, epsilon 0.05rad -> nearest BAM boundaries.
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    card_begin_angle(a as angle);
}
sub card_wait(frames: int) {
    for i in 0..frames {
        wait(1);
        card_arm_next_step();
    }
}
